import numpy as np
from scipy.optimize import minimize

def check_n_with_minimize(n):
    N = n * (n - 1) // 2
    sum_a = n * (n**2 - n + 2) / 8
    sum_a2 = (sum(k**2 for k in range(1, N + 1)) - sum_a**2) / (n - 2)

    def objective(a):
        # We want the sums to be 1, 2, ..., N
        # A good objective is to minimize the variance of the sums from {1, ..., N}
        # But we don't know the permutation. 
        # So we can minimize the difference between the sorted sums and sorted {1, ..., N}.
        sums = []
        for i in range(n):
            for j in range(i + 1, n):
                sums.append(a[i] + a[j])
        sums.sort()
        target = list(range(1, N + 1))
        return sum((s - t)**2 for s, t in zip(sums, target))

    # Constraints: sum(a) = sum_a, sum(a^2) = sum_a2, a_i are distinct
    cons = [
        {'type': 'eq', 'fun': lambda a: np.sum(a) - sum_a},
        {'type': 'eq', 'fun': lambda a: np.sum(a**2) - sum_a2}
    ]

    # Initial guess
    a0 = np.linspace(0, 10, n)

    res = minimize(objective, a0, constraints=cons)
    return res.fun, res.x

for n in range(3, 8):
    val, x = check_n_with_minimize(n)
    print(f"n={n}, min_obj={val:.4f}, x={x}")

import numpy as np
from scipy.optimize import minimize

def check_n_with_minimize(n, trials=20):
    N = n * (n - 1) // 2
    sum_a = n * (n**2 - n + 2) / 8
    sum_a2 = (sum(k**2 for k in range(1, N + 1)) - sum_a**2) / (n - 2)

    def objective(a):
        sums = []
        for i in range(n):
            for j in range(i + 1, n):
                sums.append(a[i] + a[j])
        sums.sort()
        target = list(range(1, N + 1))
        return sum((s - t)**2 for s, t in zip(sums, target))

    cons = [
        {'type': 'eq', 'fun': lambda a: np.sum(a) - sum_a},
        {'type': 'eq', 'fun': lambda a: np.sum(a**2) - sum_a2}
    ]

    min_val = float('inf')
    best_x = None

    for _ in range(trials):
        a0 = np.random.uniform(-N, N, n)
        res = minimize(objective, a0, constraints=cons)
        if res.fun < min_val:
            min_val = res.fun
            best_x = res.x

    return min_val, best_x

for n in range(5, 9):
    val, x = check_n_with_minimize(n)
    print(f"n={n}, min_obj={val:.4f}")

import itertools

def check_n_integers(n):
    N = n * (n - 1) // 2
    target_set = set(range(1, N + 1))

    # Pre-calculate the possible range for x_i
    # We know x_1 + x_2 = 1 and x_{n-1} + x_n = N
    # So x_1 <= 0 and x_n >= N/2
    # Also x_1 < x_2 < ... < x_n

    for x1 in range(-N, 1):
        x2 = 1 - x1
        if x2 <= x1: continue

        # For n=6, we need x_3, x_4, x_5, x_6
        # x_2 < x_3 < x_4 < x_5 < x_6
        # x_5 + x_6 = 15
        for x3 in range(x2 + 1, 15):
            for x4 in range(x3 + 1, 15):
                for x5 in range(x4 + 1, 15):
                    x6 = 15 - x5
                    if x6 > x5:
                        x = (x1, x2, x3, x4, x5, x6)
                        sums = set()
                        for i in range(n):
                            for j in range(i+1, n):
                                sums.add(x[i] + x[j])
                        if sums == target_set:
                            return x
    return None

print(f"n=6 (integers): {check_n_integers(6)}")
